using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
        new() { Id = "ENG", Name = "English", Description = "Study of literature, writing, and communication." },
        new() { Id = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = "HIST", Name = "History", Description = "Study of past events and human civilization." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Instructor = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT.", Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = "CS", IsFeatured = true },
        new() { Id = 2, CourseCode = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming).", Credits = 4, Instructor = "Dr. James Park", InstructorBio = "Dr. Park is a researcher in algorithm optimization with publications in ACM and IEEE journals.", Schedule = "Tue/Thu 10:30 AM–12:00 PM", DepartmentId = "CS", IsFeatured = true },
        new() { Id = 3, CourseCode = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, transaction processing, and introduction to NoSQL databases.", Credits = 3, Instructor = "Prof. Maria Rodriguez", InstructorBio = "Prof. Rodriguez spent 10 years in industry at Oracle before joining academia. She specializes in distributed systems.", Schedule = "Mon/Wed 2:00–3:30 PM", DepartmentId = "CS" },
        new() { Id = 4, CourseCode = "MATH 151", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Instructor = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator with a focus on making advanced mathematics accessible to all students.", Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = "MATH", IsFeatured = true },
        new() { Id = 5, CourseCode = "MATH 250", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations.", Credits = 3, Instructor = "Dr. Emily Zhao", InstructorBio = "Dr. Zhao's research focuses on numerical linear algebra and its applications in machine learning.", Schedule = "Tue/Thu 1:00–2:30 PM", DepartmentId = "MATH" },
        new() { Id = 6, CourseCode = "ENG 101", Title = "College Writing", Description = "Develop skills in academic writing, critical reading, and argumentation. Emphasis on clear, evidence-based prose.", Credits = 3, Instructor = "Prof. David Okafor", InstructorBio = "Prof. Okafor is a published author and writing coach with expertise in rhetoric and composition.", Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = "ENG" },
        new() { Id = 7, CourseCode = "ENG 220", Title = "American Literature", Description = "Survey of major American literary works from the colonial period to the present. Includes fiction, poetry, and essays.", Credits = 3, Instructor = "Dr. Lisa Thompson", InstructorBio = "Dr. Thompson specializes in 20th-century American fiction and has published extensively on Faulkner and Morrison.", Schedule = "Tue/Thu 9:00–10:30 AM", DepartmentId = "ENG", IsFeatured = true },
        new() { Id = 8, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Instructor = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an experimental physicist whose research involves quantum optics and photonics.", Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:00 PM", DepartmentId = "PHYS" },
        new() { Id = 9, CourseCode = "PHYS 205", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Instructor = "Dr. Priya Nair", InstructorBio = "Dr. Nair holds multiple patents in electromagnetic sensor design and brings real-world applications to the classroom.", Schedule = "Tue/Thu 11:00 AM–12:30 PM", DepartmentId = "PHYS" },
        new() { Id = 10, CourseCode = "HIST 110", Title = "World History to 1500", Description = "Survey of global civilizations from prehistory through the late medieval period, covering political, social, and cultural developments.", Credits = 3, Instructor = "Dr. Michael Adams", InstructorBio = "Dr. Adams is an archaeologist and historian specializing in ancient Mediterranean civilizations.", Schedule = "Mon/Wed 3:00–4:30 PM", DepartmentId = "HIST" },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(string id) =>
        _departments.FirstOrDefault(d => d.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetCourses(string? departmentId = null, string? searchTerm = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

